// Add this function to the TOP of the JS file (Outside DOMContentLoaded)
function confirmLogout(e) {
    e.preventDefault();
    if (confirm("Are you sure you want to log out?")) {
        localStorage.removeItem('accessToken');
        sessionStorage.removeItem('accessToken'); 
        window.location.href = 'login.html';
    }
}

document.addEventListener('DOMContentLoaded', () => {
    const API_BASE_URL = "http://127.0.0.1:8000";
    const token = localStorage.getItem('accessToken');
    if (!token) { window.location.href = 'login.html'; return; }

    let allCertificates = [];

    // --- 1. Render Function ---
    const renderCertificates = (certs) => {
        const listContainer = document.getElementById('certificateList');
        listContainer.innerHTML = '';

        if (certs.length === 0) {
            listContainer.innerHTML = '<p style="text-align:center; padding:2rem; color:gray;">No matching certificates.</p>';
            return;
        }

        certs.forEach(cert => {
            const issueDate = new Date(cert.issue_date).toLocaleDateString();

            // --- STATUS BADGE LOGIC (COLOR CODED) ---
            let statusText = cert.status.replace('_', ' ');
            let statusClass = 'status-pending'; 

            if (cert.status === 'active') {
                statusClass = 'status-active';
            } else if (cert.status === 'revoked' || cert.status === 'expired') {
                statusClass = 'status-revoked'; 
            }

            const statusBadge = `<span class="status-pill ${statusClass}">${statusText.toUpperCase()}</span>`;
            // --- END STATUS LOGIC ---

            const isPending = cert.status === 'pending_approval';
            const isRevoked = cert.status === 'revoked';

            let buttons = '';
            if (isPending) {
                buttons = `
                    <button class="icon-btn" title="Preview" onclick="openPreview(${cert.id})"><i data-feather="eye"></i></button>
                    <button class="icon-btn btn-red" title="Delete" onclick="openDeleteModal(${cert.id}, '${cert.recipient_name}')"><i data-feather="trash-2"></i></button>
                `;
            } else {
                buttons = `
                    <button class="icon-btn" title="Preview" onclick="openPreview(${cert.id})"><i data-feather="eye"></i></button>

                    <!-- CRITICAL FIX: Pass the ID, Email, and Name to the sendEmail function -->
                    <button class="icon-btn" title="Email" ${isRevoked ? 'disabled style="opacity:0.5"' : ''} 
                        onclick="sendEmail(${cert.id}, '${cert.recipient_email}', '${cert.recipient_name}')">
                        <i data-feather="mail"></i>
                    </button>

                    <button class="icon-btn" title="QR" ${isRevoked ? 'disabled style="opacity:0.5"' : ''} onclick="showQr('${cert.certificate_uid}')"><i data-feather="grid"></i></button>
                    <button class="icon-btn btn-red" title="Revoke" ${isRevoked ? 'disabled style="opacity:0.5"' : ''} onclick="revokeCert(${cert.id})"><i data-feather="slash"></i></button>
                    <button class="icon-btn btn-red" title="Delete" onclick="openDeleteModal(${cert.id}, '${cert.recipient_name}')"><i data-feather="trash-2"></i></button>
                `;
            }

            const itemHTML = `
                <div class="cert-list-item">
                    <div class="cert-info">
                        <div class="cert-icon"><i data-feather="file-text"></i></div>
                        <div class="cert-details">
                            <h4>${cert.course_title}</h4>
                            <p>To: <strong>${cert.recipient_name}</strong> • ${issueDate}</p>
                            <p><small style="font-family:monospace; color:#A3AED0;">${cert.certificate_uid}</small> • ${statusBadge}</p>
                        </div>
                    </div>
                    <div class="action-btn-group">${buttons}</div>
                </div>
            `;
            listContainer.insertAdjacentHTML('beforeend', itemHTML);
        });
        feather.replace();
    };

    // --- 2. Filter Logic (Remains the same) ---
    const applyFilters = () => {
        // ... (logic remains the same) ...
        const text = document.getElementById('certSearchInput').value.toLowerCase();
        const status = document.getElementById('statusFilter').value;
        const course = document.getElementById('courseFilter').value;

        const filtered = allCertificates.filter(c => {
            const textMatch = c.recipient_name.toLowerCase().includes(text) || 
                              c.certificate_uid.toLowerCase().includes(text);

            let statusMatch = true;
            if (status === 'active') statusMatch = c.status === 'active';
            if (status === 'pending') statusMatch = c.status === 'pending_approval';
            if (status === 'revoked') statusMatch = c.status === 'revoked' || c.status === 'expired';

            const courseMatch = course === 'all' || c.course_title === course;

            return textMatch && statusMatch && courseMatch;
        });

        renderCertificates(filtered);
    };

    // --- 3. Populate Course Dropdown (Remains the same) ---
    const populateCourses = (certs) => {
        // ... (logic remains the same) ...
        const courseSet = new Set(certs.map(c => c.course_title));
        const select = document.getElementById('courseFilter');
        select.innerHTML = '<option value="all">All Courses</option>';

        courseSet.forEach(course => {
            const opt = document.createElement('option');
            opt.value = course;
            opt.textContent = course;
            select.appendChild(opt);
        });
    };

    // --- 4. Load Data (Remains the same) ---
    const loadCertificates = async () => {
        try {
            const res = await fetch(`${API_BASE_URL}/certificates/`, { headers: { 'Authorization': `Bearer ${token}` } });
            if (res.ok) {
                allCertificates = await res.json();
                populateCourses(allCertificates); 
                renderCertificates(allCertificates);
            }
        } catch(e) { console.error(e); }
    };

    // --- Listeners ---
    document.getElementById('certSearchInput').addEventListener('input', applyFilters);
    document.getElementById('statusFilter').addEventListener('change', applyFilters);
    document.getElementById('courseFilter').addEventListener('change', applyFilters);

    // --- Global Helpers (Modal Logic) ---
    window.openPreview = async (id) => {
        try {
            const res = await fetch(`${API_BASE_URL}/certificates/${id}/preview`, { headers: { 'Authorization': `Bearer ${token}` } });
            if(res.ok) window.open(URL.createObjectURL(await res.blob()), '_blank');
            else alert("Preview not available");
        } catch(e) {}
    };

    // --- NEW/UPDATED: Send Email (Calls the new backend endpoint) ---
    window.sendEmail = async (certId, email, name) => {
        if(!email) return alert("Error: Recipient email is missing for this certificate.");
        if(!confirm(`Send certificate to ${name} at ${email}?`)) {
            return;
        }

        try {
            const res = await fetch(`${API_BASE_URL}/certificates/${certId}/send-email`, {
                method: 'POST',
                headers: { 'Authorization': `Bearer ${token}` } // No Content-Type needed for empty POST body
            });

            const data = await res.json();

            if (res.ok) {
                alert(data.message || `✅ Email successfully triggered for ${email}`);
            } else {
                throw new Error(data.detail || "Email failed to send.");
            }
        } catch (e) {
            alert("⚠️ Error: " + e.message);
        }
    };
    // ------------------------------------------------------------------

    // --- Show QR Code ---
    window.showQr = async (uid) => {
        try {
            const res = await fetch(`${API_BASE_URL}/certificates/${uid}/qr`, { headers: { 'Authorization': `Bearer ${token}` } });
            if (res.ok) {
                const blob = await res.blob();
                const url = URL.createObjectURL(blob);
                // Create a temporary layout image element to show the user
                const img = document.createElement('img');
                img.src = url;
                img.style.maxWidth = '300px';

                const modal = document.createElement('div');
                modal.style.cssText = "position:fixed;top:50%;left:50%;transform:translate(-50%,-50%);background:white;padding:2rem;box-shadow:0 10px 25px rgba(0,0,0,0.1);border-radius:12px;z-index:9999;text-align:center;";
                modal.innerHTML = `<h3>Certificate QR Code</h3><p style="color:gray;margin-bottom:1rem;">Scan to verify validity</p>`;
                modal.appendChild(img);

                const closeBtn = document.createElement('button');
                closeBtn.innerText = "Close";
                closeBtn.style.cssText = "display:block;margin:1rem auto 0;padding:0.5rem 1.5rem;background:#4F46E5;color:white;border:none;border-radius:6px;cursor:pointer;";
                closeBtn.onclick = () => document.body.removeChild(modal);
                modal.appendChild(closeBtn);

                document.body.appendChild(modal);
            } else {
                alert("QR Code generation failed");
            }
        } catch(e) { console.error(e); }
    };

    // --- 🔑 WORKING REVOCATION PIPELINE FIX ---
    window.revokeCert = async (id) => {
        // 1. Prompt the user to enter a reason for revocation
        const reason = prompt("Please enter the reason for revoking this certificate:");
        if (reason === null) return; // Stop execution if they click cancel

        try {
            // 2. Fetch request passing strict numeric id and headers
            const response = await fetch(`${API_BASE_URL}/certificates/${id}/revoke`, { 
                method: 'POST', 
                headers: { 
                    'Authorization': `Bearer ${token}`,
                    'Content-Type': 'application/json' // MANDATORY
                },
                body: JSON.stringify({ 
                    reason: reason || "No reason provided from dashboard." // MANDATORY: Matches Pydantic schemas schema
                })
            });

            if (response.ok) {
                alert("Certificate successfully revoked!");
                window.location.reload(); // Refresh the list view to display the updated state
            } else {
                const errorData = await response.json();
                alert("Error: " + (errorData.detail || "Failed to revoke certificate."));
            }
        } catch (err) {
            console.error("Revocation process failed:", err);
            alert("Network error. Could not reach server.");
        }
    };

    // --- Delete Modal Logic Placeholder ---
    window.openDeleteModal = (id, name) => {
        if(confirm(`Are you sure you want to completely delete the certificate for ${name}?`)) {
            fetch(`${API_BASE_URL}/certificates/${id}`, {
                method: 'DELETE',
                headers: { 'Authorization': `Bearer ${token}` }
            }).then(res => {
                if(res.ok) window.location.reload();
            });
        }
    };

    // Initial database pull execution 
    loadCertificates();



    // Issue Modal
    document.getElementById('issueCertBtn').onclick = () => document.getElementById('issueCertModal').style.display = 'flex';
    document.getElementById('closeModalBtn').onclick = () => document.getElementById('issueCertModal').style.display = 'none';

    document.getElementById('issueCertForm').addEventListener('submit', async (e) => {
        e.preventDefault();
        const fd = new FormData();
        fd.append('recipient_name', document.getElementById('recipientName').value);
        fd.append('recipient_email', document.getElementById('recipientEmail').value);
        fd.append('course_title', document.getElementById('courseTitle').value);
        fd.append('course_duration', document.getElementById('courseDuration').value); 
        fd.append('completion_date', document.getElementById('completionDate').value);
        const file = document.getElementById('recipientPhoto').files[0];
        if(file) fd.append('recipient_photo', file);

        const res = await fetch(`${API_BASE_URL}/certificates/`, { method: 'POST', headers: { 'Authorization': `Bearer ${token}` }, body: fd });
        if(res.ok) { alert("Issued!"); document.getElementById('issueCertModal').style.display = 'none'; loadCertificates(); }
        else { const d = await res.json(); alert(d.detail); }
    });

    // User Info
    fetch(`${API_BASE_URL}/companies/me`, { headers: { 'Authorization': `Bearer ${token}` } })
        .then(r => r.json())
        .then(u => {
            document.getElementById('userName').textContent = u.name;
            document.getElementById('userInitial').textContent = u.name[0];
        });

    document.getElementById('logoutButton').onclick = () => { localStorage.clear(); window.location.href = 'login.html'; };

    loadCertificates();
});

const API_BASE_URL = "http://127.0.0.1:8000";
const loginForm = document.getElementById('loginForm');
const alertBox = document.getElementById('alert-message');

function showMsg(msg, type='error') {
    alertBox.textContent = msg;
    alertBox.className = `alert-message alert-${type}`;
    alertBox.style.display = 'block';
}

if(loginForm) {
    loginForm.addEventListener('submit', async (e) => {
        e.preventDefault();
        const btn = loginForm.querySelector('button');
        btn.disabled = true; btn.textContent = "Logging in...";

        const formData = new FormData(loginForm);
        try {
            const res = await fetch(`${API_BASE_URL}/auth/login`, { method: 'POST', body: formData });
            const data = await res.json();

            if(!res.ok) throw new Error(data.detail);

            localStorage.setItem('accessToken', data.access_token);

            // Check Role
            if(data.is_admin) {
                window.location.href = 'admin_dashboard.html';
            } else {
                // Double check if Super Admin via /companies/me
                const meRes = await fetch(`${API_BASE_URL}/companies/me`, { headers: { 'Authorization': `Bearer ${data.access_token}` } });
                const me = await meRes.json();
                if(me.is_admin) window.location.href = 'admin_dashboard.html';
                else window.location.href = 'dashboard.html';
            }
        } catch(err) {
            showMsg(err.message);
            btn.disabled = false; btn.textContent = "Login";
        }
    });
}

// frontend/js/workers.js (FINAL VERSION - UNEDITABLE WORKER ID)

// Add this function to the TOP of the JS file (Outside DOMContentLoaded)
function confirmLogout(e) {
    e.preventDefault();
    if (confirm("Are you sure you want to log out?")) {
        localStorage.removeItem('accessToken');
        sessionStorage.removeItem('accessToken'); // Clear both
        window.location.href = 'login.html';
    }
}

document.addEventListener('DOMContentLoaded', () => {
    const API_BASE_URL = "http://127.0.0.1:8000";
    const token = localStorage.getItem('accessToken');
    if (!token) { window.location.href = 'login.html'; return; }

    const fetchAPI = async (endpoint, options = {}) => {
        const res = await fetch(`${API_BASE_URL}${endpoint}`, {
            ...options,
            headers: { 'Authorization': `Bearer ${token}`, 'Content-Type': 'application/json', ...options.headers }
        });
        return res;
    };

    let allWorkers = [];

    // --- RENDER ---
    const loadWorkers = async () => {
        const res = await fetchAPI('/workers/');
        const tbody = document.getElementById('workersTableBody');
        if (res.ok) {
            allWorkers = await res.json();
            renderWorkers(allWorkers);
        }
    };

    const renderWorkers = (workers) => {
        const tbody = document.getElementById('workersTableBody');
        tbody.innerHTML = workers.map(w => `
            <tr>
                <td>${w.worker_id}</td>
                <td><strong>${w.name}</strong></td>
                <td>${w.email}</td>
                <td>${w.role}</td>
                <td><span class="status-pill status-${w.status}">${w.status}</span></td>
                <td>
                    <div class="action-btn-group">
                        <button onclick="editWorker(${w.id})" class="icon-btn" title="Edit"><i data-feather="edit"></i></button>
                        <button onclick="deleteWorker(${w.id})" class="icon-btn btn-red" title="Delete"><i data-feather="trash-2"></i></button>
                    </div>
                </td>
            </tr>
        `).join('');
        feather.replace();
    };

    // --- SEARCH ---
    document.getElementById('workerSearchInput').addEventListener('input', (e) => {
        const term = e.target.value.toLowerCase();
        const filtered = allWorkers.filter(w => 
            w.name.toLowerCase().includes(term) || 
            w.worker_id.toLowerCase().includes(term) ||
            w.email.toLowerCase().includes(term)
        );
        renderWorkers(filtered);
    });

    // --- PASSWORD TOGGLE LOGIC ---
    const toggleBtn = document.getElementById('toggleWorkerPass');
    const passInput = document.getElementById('workerPassword');

    if (toggleBtn) {
        toggleBtn.addEventListener('click', () => {
            const type = passInput.getAttribute('type') === 'password' ? 'text' : 'password';
            passInput.setAttribute('type', type);
            const iconName = type === 'password' ? 'eye' : 'eye-off';
            toggleBtn.setAttribute('data-feather', iconName);
            feather.replace();
        });
    }

    // --- MODAL ACTIONS ---
    window.editWorker = async (id) => {
        const res = await fetchAPI(`/workers/${id}`);
        if(res.ok) {
            const w = await res.json();
            document.getElementById('editWorkerId').value = w.id;
            document.getElementById('workerName').value = w.name;
            document.getElementById('workerEmail').value = w.email;

            // Set Worker ID and make it UN-EDITABLE
            const wIdInput = document.getElementById('workerId');
            wIdInput.value = w.worker_id;
            wIdInput.readOnly = true; 
            wIdInput.style.backgroundColor = "#f0f0f0"; // Visual cue it's locked

            document.getElementById('workerRole').value = w.role;

            passInput.value = "";
            passInput.placeholder = "Leave blank to keep current";

            document.getElementById('modalTitle').textContent = "Edit Worker";
            document.getElementById('addWorkerModal').style.display = 'flex';
        }
    };

    window.deleteWorker = async (id) => {
        if(confirm("Delete worker?")) {
            await fetchAPI(`/workers/${id}`, { method: 'DELETE' });
            loadWorkers();
        }
    };

    document.getElementById('addWorkerBtn').onclick = () => {
        document.getElementById('addWorkerForm').reset();
        document.getElementById('editWorkerId').value = "";

        passInput.placeholder = "Set Password";

        // --- AUTO ID GENERATION & LOCKING ---
        let rnd, workerId;
        do {
            rnd = Math.floor(Math.random() * 900) + 100;
            workerId = `EMP${rnd}`;
        } while (allWorkers.some(w => w.worker_id === workerId));

        const wIdInput = document.getElementById('workerId');
        wIdInput.value = workerId;
        wIdInput.readOnly = true; // --- MAKE UN-EDITABLE ---
        wIdInput.style.backgroundColor = "#f0f0f0"; 

        document.getElementById('modalTitle').textContent = "Add New Worker";
        document.getElementById('addWorkerModal').style.display = 'flex';
    };

    document.getElementById('closeModalBtn').onclick = () => document.getElementById('addWorkerModal').style.display = 'none';

    document.getElementById('addWorkerForm').addEventListener('submit', async (e) => {
        e.preventDefault();
        const id = document.getElementById('editWorkerId').value;
        const data = {
            name: document.getElementById('workerName').value,
            email: document.getElementById('workerEmail').value,
            worker_id: document.getElementById('workerId').value,
            role: document.getElementById('workerRole').value,
            password: passInput.value
        };
        const method = id ? 'PUT' : 'POST';
        const url = id ? `/workers/${id}` : '/workers/';

        const res = await fetchAPI(url, { method: method, body: JSON.stringify(data) });
        if(res.ok) {
            document.getElementById('addWorkerModal').style.display = 'none';
            loadWorkers();
        } else {
            const err = await res.json();
            alert("Error: " + err.detail);
        }
    });

    // User Info
    fetch(`${API_BASE_URL}/companies/me`, { headers: { 'Authorization': `Bearer ${token}` } })
        .then(r => r.json())
        .then(u => {
            document.getElementById('userName').textContent = u.name;
            document.getElementById('userInitial').textContent = u.name[0];
        });

    const logBtn = document.getElementById('logoutButton');
    if (logBtn) {
        logBtn.onclick = () => { localStorage.clear(); window.location.href = 'login.html'; };
    }

    loadWorkers();
});

document.addEventListener('DOMContentLoaded', () => {
    const API_BASE_URL = "http://127.0.0.1:8000";
    const token = localStorage.getItem('accessToken');

    if (!token) { window.location.href = 'login.html'; return; }

    let allLogs = [];

    // --- 1. Render Function ---
    const renderLogs = (logs) => {
        const tbody = document.getElementById('auditLogTableBody');
        tbody.innerHTML = '';

        if (logs.length === 0) {
            tbody.innerHTML = '<tr><td colspan="4" style="text-align:center; padding:2rem; color:gray">No matching activity found.</td></tr>';
            return;
        }

        logs.forEach(log => {
            const dateObj = new Date(log.timestamp);
            const dateStr = dateObj.toLocaleDateString();
            const timeStr = dateObj.toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'});

            let actorDisplay = log.actor_type === 'company' 
                ? '<span class="status-pill status-active">Admin</span>' 
                : `<span class="status-pill status-pending">Staff ${log.actor_id}</span>`;

            // Highlight keywords
            let details = log.details || "";
            if (details.includes("Deleted")) details = `<span style="color:#EF4444; font-weight:bold;">${details}</span>`;

            const row = `
                <tr>
                    <td>
                        <div style="font-weight:600; color:#2B3674;">${dateStr}</div>
                        <div style="font-size:0.8rem; color:#A3AED0;">${timeStr}</div>
                    </td>
                    <td style="text-transform:capitalize; font-weight:600;">${log.event_type.replace(/_/g, ' ')}</td>
                    <td>${actorDisplay}</td>
                    <td>${details}</td>
                </tr>
            `;
            tbody.insertAdjacentHTML('beforeend', row);
        });
    };

    // --- 2. Filter Logic (Unified) ---
    const applyFilters = () => {
        const searchTerm = document.getElementById('logSearchInput').value.toLowerCase();
        const filterType = document.getElementById('logFilterSelect').value;

        const filtered = allLogs.filter(log => {
            const type = (log.event_type || "").toLowerCase();
            const details = (log.details || "").toLowerCase();

            // Check Dropdown
            let typeMatch = true;
            if (filterType !== 'all') {
                typeMatch = type.includes(filterType);
            }

            // Check Search Box
            const textMatch = type.includes(searchTerm) || details.includes(searchTerm);

            return typeMatch && textMatch;
        });

        renderLogs(filtered);
    };

    // --- 3. Fetch Data ---
    async function loadAuditLogs() {
        try {
            const res = await fetch(`${API_BASE_URL}/dashboard/audit-logs`, {
                headers: { 'Authorization': `Bearer ${token}` }
            });
            if (!res.ok) throw new Error("Failed");
            allLogs = await res.json(); 
            renderLogs(allLogs);
        } catch (err) {
            console.error(err);
        }
    }

    // --- Listeners ---
    document.getElementById('logSearchInput').addEventListener('input', applyFilters);
    document.getElementById('logFilterSelect').addEventListener('change', applyFilters);

    // Header Info
    fetch(`${API_BASE_URL}/companies/me`, { headers: { 'Authorization': `Bearer ${token}` } })
        .then(r => r.json())
        .then(u => {
            document.getElementById('userName').textContent = u.name;
            document.getElementById('userInitial').textContent = u.name[0];
        });

    document.getElementById('logoutButton').onclick = () => {
        localStorage.clear(); window.location.href = 'login.html';
    };

    loadAuditLogs();
});

// Add this function to the TOP of the JS file (Outside DOMContentLoaded)

function confirmLogout(e) {
