    if (confirm("Are you sure you want to log out?")) {
        localStorage.removeItem('accessToken');
        sessionStorage.removeItem('accessToken');
        window.location.href = 'staff_login.html'; // Redirect to staff login
    }
}

document.addEventListener('DOMContentLoaded', async () => {
    const API_BASE_URL = "http://127.0.0.1:8000";
    const token = localStorage.getItem('accessToken') || sessionStorage.getItem('accessToken');

    if (!token) {
        window.location.href = 'staff_login.html';
        return;
    }

    // --- 1. User Info from Token ---
    function parseJwt(token) {
        try { return JSON.parse(atob(token.split('.')[1])); } catch (e) { return {}; }
    }
    const user = parseJwt(token);
    document.getElementById('activeIssuerName').textContent = user.name || "Staff";
    document.getElementById('userInitial').textContent = (user.name || "S").charAt(0).toUpperCase();

    // --- 2. Fetch Stats & Pending List ---
    async function loadMyData() {
    try {
        // Backend now filters by worker_id, so this returns only this worker's certificates
        const res = await fetch(`${API_BASE_URL}/certificates/`, {
            headers: { 'Authorization': `Bearer ${token}` }
        });

        if(!res.ok) throw new Error("Failed to fetch data");

        const myCerts = await res.json(); 

        const pending = myCerts.filter(c => c.status === 'pending_approval');
        const active = myCerts.filter(c => c.status === 'active');

        // Update Stats
        document.getElementById('myTotalIssued').textContent = active.length;
        document.getElementById('myTotalPending').textContent = pending.length;

        // Update Table
        const tbody = document.getElementById('myPendingTable');
        tbody.innerHTML = '';

        if (pending.length === 0) {
            tbody.innerHTML = '<tr><td colspan="3" style="color:var(--text-gray); text-align:center; padding:1rem;">No pending certificates found.</td></tr>';
        } else {
            pending.forEach(c => {
                tbody.innerHTML += `
                    <tr>
                        <td><strong>${c.recipient_name}</strong></td>
                        <td>${c.course_title}</td>
                        <td><span class="status-pill status-pending">Pending</span></td>
                    </tr>
                `;
            });
        }

    } catch (err) {
        console.error("Load Data Error:", err);
    }
}
// --- 3. Load Worker's Activity Feed (NEW) ---
async function loadMyActivity() {
    const feed = document.getElementById('workerActivityFeed');
    feed.innerHTML = '<li style="color:var(--text-gray); padding:10px;">Loading activity...</li>';

    try {
        const res = await fetch(`${API_BASE_URL}/workers/me/logs`, {
            headers: { 'Authorization': `Bearer ${token}` }
        });

        if (!res.ok) throw new Error("Failed to fetch activity");

        const logs = await res.json();

        if (logs.length === 0) {
            feed.innerHTML = '<li style="color:var(--text-gray); padding:10px;">No recent actions logged.</li>';
            return;
        }

        feed.innerHTML = logs.map(log => {
            let icon = 'clock';
            let color = '#3A86FF';
            let details = log.details.replace('Staff Login:', 'Logged in.');
            if (log.event_type.includes('issue')) { icon = 'file-plus'; color = '#10B981'; details = details.replace('Issued by Staff', 'Issued Cert'); }
            if (log.event_type.includes('delete')) { icon = 'trash-2'; color = '#EF4444'; }
            if (log.event_type.includes('bulk_import')) { icon = 'upload-cloud'; color = '#F59E0B'; }

            return `
                <li style="display:flex; gap:15px; padding:8px 0; border-bottom:1px dashed #eee;">
                    <div style="color:${color};"><i data-feather="${icon}" style="width:18px; height:18px;"></i></div>
                    <div>
                        <p style="font-size:0.9rem; color:var(--text-dark); margin:0;">${details}</p>
                        <span style="font-size:0.75rem; color:var(--text-gray);">${log.timestamp}</span>
                    </div>
                </li>
            `;
        }).join('');

        feather.replace();

    } catch(err) {
        feed.innerHTML = '<li style="color:red; padding:10px;">Error loading activity.</li>';
    }
}

    // --- 3. Handle Bulk Import ---
    const bulkForm = document.getElementById('bulkImportForm');
    if(bulkForm) {
        bulkForm.addEventListener('submit', async (e) => {
            e.preventDefault();
            const fileInput = document.getElementById('csvFile');
            const file = fileInput.files[0];
            if (!file) return;

            const formData = new FormData();
            formData.append("file", file);

            const btn = e.target.querySelector('button');
            const oldHtml = btn.innerHTML;
            btn.innerHTML = `<i data-feather="loader" class="feather-spin"></i> Processing...`; 
            btn.disabled = true;
            feather.replace();

            try {
                const res = await fetch(`${API_BASE_URL}/certificates/bulk-import`, {
                    method: 'POST', 
                    headers: { 'Authorization': `Bearer ${token}` }, 
                    body: formData
                });

                const data = await res.json();

                if (res.ok) { 
                    alert(data.message); 
                    fileInput.value = ""; 
                    document.getElementById('fileNameDisplay').textContent = 'Click to Choose File (CSV)';
                    document.getElementById('fileNameDisplay').style.color = 'var(--text-dark)';
                    loadMyData(); 
                } else { 
                    alert("Error: " + (data.detail || "Upload failed")); 
                }
            } catch (err) { 
                console.error(err);
                alert("Network error during upload"); 
            } finally { 
                btn.innerHTML = oldHtml; 
                btn.disabled = false; 
                feather.replace();
            }
        });
    }

    // --- 4. Handle Single Issue ---
    const modal = document.getElementById('issueCertModal');

    if(document.getElementById('navIssueBtn')) {
        document.getElementById('navIssueBtn').addEventListener('click', (e) => {
            e.preventDefault();
            modal.style.display = 'flex';
        });
    }

    if(document.getElementById('closeModalBtn')) {
        document.getElementById('closeModalBtn').addEventListener('click', () => {
            modal.style.display = 'none';
        });
    }

    const issueForm = document.getElementById('issueCertForm');
    if(issueForm) {
        issueForm.addEventListener('submit', async (e) => {
            e.preventDefault();
            const btn = e.target.querySelector('button');
            const oldText = btn.textContent;
            btn.textContent = "Submitting..."; btn.disabled = true;

            const formData = new FormData();
            formData.append('recipient_name', document.getElementById('recipientName').value);
            formData.append('recipient_email', document.getElementById('recipientEmail').value);
            formData.append('course_title', document.getElementById('courseTitle').value);
            formData.append('course_duration', document.getElementById('courseDuration').value);
            formData.append('completion_date', document.getElementById('completionDate').value);

            const photo = document.getElementById('recipientPhoto').files[0];
            if (photo) formData.append('recipient_photo', photo);

            try {
                const res = await fetch(`${API_BASE_URL}/certificates/`, {
                    method: 'POST', headers: { 'Authorization': `Bearer ${token}` }, body: formData
                });

                if (res.ok) {
                    alert("Certificate created! Pending approval.");
                    modal.style.display = 'none';
                    e.target.reset();
                    loadMyData(); 
                } else {
                    const d = await res.json();
                    alert("Error: " + (d.detail || "Failed"));
                }
            } catch (err) {
                alert("Error submitting form.");
            } finally {
                btn.textContent = oldText; 
                btn.disabled = false;
            }
        });
    }

    // --- 5. Helpers (Download Template) ---
    window.downloadTemplate = () => {
    const csvContent = "data:text/csv;charset=utf-8,Recipient Name,Recipient Email,Course Title,Course Duration\nJohn Doe,john@example.com,Python Basics,4 Weeks";
        const encodedUri = encodeURI(csvContent);
        const link = document.createElement("a");
        link.setAttribute("href", encodedUri);
        link.setAttribute("download", "certificate_template.csv");
        document.body.appendChild(link);
        link.click();
    };

    document.getElementById('logoutButton').addEventListener('click', () => {
        localStorage.removeItem('accessToken');
        window.location.href = 'staff_login.html';
    });

    // Init
    loadMyData();
    loadMyActivity(); 
});

document.addEventListener('DOMContentLoaded', () => {
    const API_BASE_URL = "http://127.0.0.1:8000";
    const token = localStorage.getItem('accessToken');

    if (!token) { window.location.href = 'login.html'; return; }

    let allCompanies = [];
    let allLogs = [];

    // --- 1. Fetch Helper ---
    const fetchAPI = async (endpoint, options = {}) => {
        const response = await fetch(`${API_BASE_URL}${endpoint}`, {
            ...options,
            headers: {
                'Authorization': `Bearer ${token}`,
                'Content-Type': 'application/json',
                ...options.headers,
            },
        });
        if (response.status === 401) { window.location.href = 'login.html'; }
        return response;
    };

    // --- 2. Navigation Logic ---
    document.querySelectorAll('.sidebar-link[data-target]').forEach(link => {
        link.addEventListener('click', () => {
            document.querySelectorAll('.sidebar-link').forEach(l => l.classList.remove('active'));
            document.querySelectorAll('.dashboard-section').forEach(s => s.classList.remove('active'));
            link.classList.add('active');
            const targetId = link.getAttribute('data-target');
            document.getElementById(targetId).classList.add('active');
        });
    });

    // --- 3. CHART RENDERING ---
    let barChartInstance = null;
    let pieChartInstance = null;

    const renderCharts = async () => {
        const res = await fetchAPI('/admin/charts/data');
        if(!res.ok) return console.error("Could not load chart data.");

        const data = await res.json();
        const monthlyData = data.monthly_issuance;
        const statusData = data.center_status;

        const labels = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];

        // A. Bar Chart (Monthly Issuance)
        const barCtx = document.getElementById('issuanceBarChart');
        if (barChartInstance) barChartInstance.destroy();
        barChartInstance = new Chart(barCtx, {
            type: 'bar',
            data: {
                labels: labels,
                datasets: [{
                    label: 'Certificates Issued',
                    data: monthlyData,
                    backgroundColor: 'rgba(58, 134, 255, 0.8)',
                    borderRadius: 5,
                }]
            },
            options: {
                responsive: true, maintainAspectRatio: false,
                plugins: { legend: { display: false } },
                scales: { y: { beginAtZero: true, ticks: { precision: 0 } } }
            }
        });

        // B. Pie Chart (Center Status)
        const pieCtx = document.getElementById('centerPieChart');
        if (pieChartInstance) pieChartInstance.destroy();

        const pieLabels = Object.keys(statusData).map(s => s.charAt(0).toUpperCase() + s.slice(1));
        const pieValues = Object.values(statusData);

        pieChartInstance = new Chart(pieCtx, {
            type: 'doughnut',
            data: {
                labels: pieLabels,
                datasets: [{
                    data: pieValues,
                    backgroundColor: [
                        '#10B981', // Verified (Green)
                        '#F59E0B', // Pending (Warning)
                        '#3A86FF', // Rejected (Blue)
                    ],
                    hoverOffset: 10
                }]
            },
            options: {
                responsive: true, maintainAspectRatio: false,
                plugins: { legend: { position: 'bottom' } }
            }
        });
    };

    // --- 4. Log Filtering & Rendering Logic ---
    const renderFullLogs = (logs) => {
    const fullLogsTable = document.getElementById('logsTableBodyFull');
    if (!fullLogsTable) return;

    fullLogsTable.innerHTML = logs.map(l => `
        <tr>
            <td>${new Date(l.timestamp).toLocaleString()}</td>
            <td>${l.event_type}</td>
            <td>${l.actor_display}</td> <!-- USE NEW FIELD -->
            <td>${l.details}</td>
        </tr>`).join('');
};

    const applyLogFilters = () => {
        const searchTerm = document.getElementById('logSearchInput').value.toLowerCase();
        const filterType = document.getElementById('logFilterType').value;

        const filtered = allLogs.filter(log => {
            const type = (log.event_type || "").toLowerCase();
            const details = (log.details || "").toLowerCase();
            const actor = (log.actor_type || "").toLowerCase();

            let typeMatch = (filterType === 'all') || type.includes(filterType);
            const textMatch = type.includes(searchTerm) || details.includes(searchTerm) || actor.includes(searchTerm);

            return typeMatch && textMatch;
        });

        renderFullLogs(filtered);
    };

    // --- 5. Load Stats & Logs ---
    const loadStatsAndLogs = async () => {
        try {
            const statsRes = await fetchAPI('/admin/stats');
            if(statsRes.ok) {
                const stats = await statsRes.json();
                document.getElementById('totalCenters').textContent = stats.total_centers || 0;
                document.getElementById('totalCerts').textContent = stats.total_certificates || 0;
                document.getElementById('pendingApprovals').textContent = stats.pending_reviews || 0;
                document.getElementById('totalWorkers').textContent = stats.total_workers || 0;
            }

            const logsRes = await fetchAPI('/admin/logs');
if(logsRes.ok) {
    allLogs = await logsRes.json();

    // Render Dashboard Overview Logs (top 5)
    const dashboardLogs = allLogs.slice(0, 5);
    document.getElementById('logsTableBody').innerHTML = dashboardLogs.map(l => `
        <tr>
            <td>${new Date(l.timestamp).toLocaleTimeString()}</td>
            <td>${l.event_type}</td>
            <td>${l.actor_display}</td> <!-- USE NEW FIELD -->
            <td>${l.details}</td>
        </tr>`).join('');

    // Initial render of the Full Logs page
    renderFullLogs(allLogs);
}
            renderCharts();
        } catch (err) { console.error("Stats/Logs error:", err); }
    };

    // --- 6. Load Companies List & Filtering ---
    const loadCompanies = async () => {
        try {
            const res = await fetchAPI('/admin/companies');
            if(!res.ok) throw new Error("Failed to load");
            allCompanies = await res.json();
            applyCompanyFilters();
        } catch (err) { document.getElementById('companiesTableBody').innerHTML = '<tr><td colspan="6" style="color:red;padding:20px;">Failed to load data</td></tr>'; }
    };

    const applyCompanyFilters = () => {
        const tbody = document.getElementById('companiesTableBody');
        const searchTerm = document.getElementById('companySearchInput').value.toLowerCase();
        const filterStatus = document.getElementById('companyFilterStatus').value;

        const filtered = allCompanies.filter(c => {
            const textMatch = c.name.toLowerCase().includes(searchTerm) || c.email.toLowerCase().includes(searchTerm);
            const statusMatch = filterStatus === 'all' || c.status === filterStatus;
            return textMatch && statusMatch;
        });

        tbody.innerHTML = filtered.map(c => `
        <tr>
            <td>#${c.id}</td>
            <td><strong>${c.name}</strong></td>
            <td>${c.email}</td>
            <td>
                <span class="status-pill status-${c.status}">
                    ${c.status.toUpperCase()}
                </span>
            </td>
            <td>${new Date(c.created_at).toLocaleDateString()}</td>
            <td>
                <button class="btn-primary" style="padding:8px 15px;" onclick="openDetailModal(${c.id})">Details</button>
            </td>
        </tr>`).join('');
    };

    // Listeners for company filters
    document.getElementById('companySearchInput').addEventListener('input', applyCompanyFilters);
    document.getElementById('companyFilterStatus').addEventListener('change', applyCompanyFilters);

    // --- 7. Load Support Tickets ---
    const loadTickets = async () => {
        const tbody = document.getElementById('supportTableBody');
        try {
            const res = await fetchAPI('/admin/tickets');
            if(!res.ok) return;
            const tickets = await res.json();

            tbody.innerHTML = tickets.map(t => `
                <tr>
                    <td>${new Date(t.created_at).toLocaleDateString()}</td>
                    <td><strong>${t.company_name}</strong></td>
                    <td>${t.subject}</td>
                    <td style="max-width:300px; font-size:0.9rem;">${t.message}</td>
                    <td><span class="status-pill status-${t.status === 'open' ? 'pending' : 'active'}">${t.status}</span></td>
                    <td>
                        ${t.status === 'open' ? 
                        `<button class="btn-primary" onclick="resolveTicket(${t.id})" style="padding:8px 15px;">Resolve</button>` : 
                        `<i data-feather="check" style="color:var(--brand-green);"></i>`}
                    </td>
                </tr>
            `).join('');
            feather.replace();
        } catch(e) { console.error(e); }
    };

    // --- 8. COMPANY DETAIL MODAL (Fully Restored Logic) ---
    window.openDetailModal = async (id) => {
        const modal = document.getElementById('companyDetailModal');
        modal.style.display = 'flex';

        try {
            // 1. Fetch Details + Stats
            const res = await fetchAPI(`/admin/companies/${id}/details`);
            if(!res.ok) throw new Error("Could not fetch details.");
            const data = await res.json();
            const c = data.company;
            const stats = data.stats;

            // 2. Populate Header & Basic Details 
            document.getElementById('detailCompanyName').textContent = c.name || "N/A";

            // Status
            document.getElementById('detailStatus').textContent = c.status;
            document.getElementById('detailStatus').className = `status-pill status-${c.status}`;

            // Contact Details
            document.getElementById('detailEmail').textContent = c.email || "N/A";
            document.getElementById('detailRegNo').textContent = c.business_reg_number || "N/A";
            document.getElementById('detailContactName').textContent = c.primary_contact_name || "N/A";
            document.getElementById('detailCitizen').textContent = c.citizenship_number || "N/A";

            // 3. Populate Stats
            document.getElementById('detailWorkers').textContent = stats.workers;
            document.getElementById('detailCertsTotal').textContent = stats.certificates;
            document.getElementById('detailCertsActive').textContent = stats.active_certs;

            // 4. Load Documents 
            const loadDoc = async (url, imgId, linkId) => {
                const docRes = await fetchAPI(url);
                const blob = await docRes.blob();
                const blobUrl = URL.createObjectURL(blob);
                document.getElementById(imgId).src = blobUrl;
                document.getElementById(linkId).href = blobUrl;
            };

            loadDoc(`/admin/companies/${id}/files/photo`, 'detailImgPhoto', 'detailDocLink');
            loadDoc(`/admin/companies/${id}/files/doc`, 'detailDocFrame', 'detailDocLink');

            // 5. Setup Buttons
            const btnApprove = document.getElementById('btnDetailApprove');
            const btnReject = document.getElementById('btnDetailReject');
            const btnDelete = document.getElementById('btnDetailDelete');

            btnApprove.style.display = c.status === 'pending' ? 'block' : 'none';
            btnReject.style.display = c.status !== 'rejected' ? 'block' : 'none';
            btnDelete.style.display = 'block';

            btnApprove.onclick = async () => { if(confirm('Approve?')) { await fetchAPI(`/admin/companies/${id}/approve`, { method: 'PUT' }); modal.style.display = 'none'; loadCompanies(); loadStatsAndLogs(); } };
            btnReject.onclick = async () => { if(confirm('Reject?')) { await fetchAPI(`/admin/companies/${id}/reject`, { method: 'PUT' }); modal.style.display = 'none'; loadCompanies(); loadStatsAndLogs(); } };
            btnDelete.onclick = async () => { if(confirm('Delete entire company?')) { await fetchAPI(`/admin/companies/${id}`, { method: 'DELETE' }); modal.style.display = 'none'; loadCompanies(); loadStatsAndLogs(); } };


        } catch(e) {
            console.error("Detail Modal Crash:", e);
            alert("Error loading application details. Check console.");
        }
    };

    // --- 9. Global Actions ---
    window.resolveTicket = async (id) => {
        if(!confirm("Mark resolved?")) return;
        await fetchAPI(`/admin/tickets/${id}/resolve`, { method: 'PUT', headers: { 'Content-Type': 'application/json' } });
        loadTickets();
    };


    // --- Init ---
    document.getElementById('logoutButton').addEventListener('click', () => {
        localStorage.removeItem('accessToken');
        window.location.href = 'login.html';



    });

    loadStatsAndLogs();
    loadCompanies();
    loadTickets();

    // Add this function to the TOP of the JS file (Outside DOMContentLoaded)



    // Attach event listeners for the Audit Logs filtering
    document.getElementById('logSearchInput').addEventListener('input', applyLogFilters);
    document.getElementById('logFilterType').addEventListener('change', applyLogFilters);


});

// frontend/js/verify.js (DEFINITIVE FIX - Using CSS Classes Safely)

document.addEventListener('DOMContentLoaded', async () => {
    const API_BASE_URL = "http://127.0.0.1:8000";

    const urlParams = new URLSearchParams(window.location.search);
    const certId = urlParams.get('id');

    const loadingState = document.getElementById('loadingState');
    const resultCard = document.getElementById('resultCard');
    const statusBanner = document.getElementById('statusBanner');
    const statusMessage = document.getElementById('statusMessage');

    // Helper to hide content (used in error path)
    function hideSuccessContent() {
        const content = resultCard.querySelectorAll(':scope > div:not(#statusBanner)');
        content.forEach(el => el.style.display = 'none');
    }

    // Helper to show error state
    function showError(msg, statusClass) {
        loadingState.style.display = 'none';
        resultCard.style.display = 'block';

        statusBanner.className = `status-banner ${statusClass}`;
        statusMessage.textContent = msg;

        // Hide all success content
        hideSuccessContent(); 

        statusBanner.style.display = 'flex'; 

        // Final icon setting - Use a simple replacement
        const iconElement = statusBanner.querySelector('i');
        if (iconElement) {
            iconElement.outerHTML = '<i data-feather="alert-triangle"></i>';
        }

        feather.replace();
    }

    // --- FINAL SUCCESS RENDERER ---
    function renderSuccess(data) {
        // 1. Restore visibility for all content blocks
        const content = resultCard.querySelectorAll(':scope > div:not(#statusBanner)');
        content.forEach(el => {
            if (el.classList.contains('cert-actions')) { el.style.display = 'flex'; } 
            else if (el.classList.contains('cert-sub-details')) { el.style.display = 'grid'; } 
            else { el.style.display = 'block'; }
        }); 

        // 2. Dynamic Status Logic
        const status = data.status.toLowerCase();
        let bannerClass = 'verified'; // Maps to status-active
        let bannerText = 'Verified Authentic';

        if (status === 'revoked') {
            bannerClass = 'revoked'; // Maps to status-revoked
            bannerText = 'Revoked: This certificate has been officially invalidated by the issuer.';
        } else if (status === 'expired') {
            bannerClass = 'expired'; // Maps to status-pending/warning color
            bannerText = 'Expired: This certificate is valid but the issue date has passed.';
        }

        // 3. Populate Details
        document.getElementById('vCourseTitle').textContent = data.course_title;
        document.getElementById('vRecipientName').textContent = data.recipient_name;
        document.getElementById('vCertID').textContent = data.certificate_uid;
        document.getElementById('vIssueDate').textContent = new Date(data.issue_date).toLocaleDateString();
        document.getElementById('vStatusText').textContent = data.status;
        document.getElementById('vHash').textContent = data.sha_hash;
        document.getElementById('vCount').textContent = data.verification_count || 0;

        // --- NEW LOGO DISPLAY (Re-run Logo Fetch from previous step) ---
        const logoPlaceholder = document.getElementById('companyLogoPlaceholder');
        const companyId = data.company_id; // <--- This reads the field we just added!

        if (logoPlaceholder && companyId) {
            const logoUrl = `${API_BASE_URL}/companies/public/logo/${companyId}`;

            // Inject Logo HTML
            logoPlaceholder.innerHTML = `<img src="${logoUrl}" alt="Company Logo" style="max-height:80px; max-width:200px; margin-bottom:10px;">`;
        }

        // 4. Update Status Banner CSS and Text
        statusBanner.className = `status-banner ${bannerClass}`;
        statusMessage.textContent = bannerText;

        // 5. Final Icon Replacement (CRITICAL FIX: Overwrite the <i> tag before final feather.replace)
        const iconElement = statusBanner.querySelector('i');
        if (iconElement) {
            const iconName = bannerClass === 'verified' ? 'check-circle' : 'alert-circle';
            // Overwrite the <i> tag, which is safer than manipulating a pre-rendered SVG
            iconElement.outerHTML = `<i data-feather="${iconName}"></i>`;
        }

        // 6. Final Display
        loadingState.style.display = 'none';
        resultCard.style.display = 'block';
        statusBanner.style.display = 'flex';
        feather.replace(); // Runs the replacement only once at the end

        // 7. Actions (Logic is correct)
        document.getElementById('downloadPdfBtn').onclick = () => {
            if (status === 'active' || status === 'expired') { 
                window.open(`${API_BASE_URL}/verification/${data.certificate_uid}/download`, '_blank');
            } else {
                alert("Download blocked: Certificate is revoked or pending.");
            }
        };

        document.getElementById('shareLinkedInBtn').onclick = () => {
            const certUrl = encodeURIComponent(window.location.href);
            const message = encodeURIComponent(`I successfully verified the ${data.course_title} certificate for ${data.recipient_name} using SkillSathi's transparent verification platform. Check authenticity here:`);
            window.open(`https://www.linkedin.com/shareArticle?mini=true&url=${certUrl}&title=${message}`, '_blank');
        };
    }
    // --- END SUCCESS RENDERER ---


    if (!certId) {
        showError("Error: No Certificate ID provided.", "not-found");
        return;
    }

    // Initial loading state
    loadingState.style.display = 'block';


    try {
        const response = await fetch(`${API_BASE_URL}/verification/${certId}`);
        const data = await response.json();

        if (!response.ok) {
            const detail = data.detail || "Verification failed due to an invalid ID or hash.";
            throw new Error(detail); 
        }

        // Success: Call the dedicated renderer function after a slight delay 
        setTimeout(() => {
            renderSuccess(data);
        }, 50);

    } catch (error) {
        console.error("Verification Page Crash (Final Fallback):", error);
        const msg = (error.message && error.message.includes("Verification failed")) ? error.message : "The certificate ID is invalid or not yet active.";
        showError(msg, "not-found");
    }
});

// Add this function to the TOP of the JS file (Outside DOMContentLoaded)

function confirmLogout(e) {
    e.preventDefault();
    if (confirm("Are you sure you want to log out?")) {
        localStorage.removeItem('accessToken');
        sessionStorage.removeItem('accessToken'); // Clear both
        window.location.href = 'login.html';
    }
}

document.addEventListener('DOMContentLoaded', () => {
    const API_BASE_URL = "http://127.0.0.1:8000";
    const token = localStorage.getItem('accessToken');
    if (!token) { window.location.href = 'login.html'; return; }

    const fetchAPI = async (endpoint, options = {}) => {
        const res = await fetch(`${API_BASE_URL}${endpoint}`, {
            ...options,
            headers: { 'Authorization': `Bearer ${token}`, ...options.headers }
        });
        return res;
    };

    // --- 1. Load Settings (Profile + Notifications + Images) ---
    async function loadSettings() {
        // A. Load Profile
        try {
            const res = await fetchAPI('/companies/me');
            if(res.ok) {
                const u = await res.json();
                if(document.getElementById('profileName')) document.getElementById('profileName').value = u.name;
                if(document.getElementById('profileEmail')) document.getElementById('profileEmail').value = u.email;
                if(document.getElementById('profilePhone')) document.getElementById('profilePhone').value = u.phone_number || "";

                // Sidebar
                if(document.getElementById('userName')) document.getElementById('userName').textContent = u.name;
                if(document.getElementById('userInitial')) document.getElementById('userInitial').textContent = u.name.charAt(0).toUpperCase();
            }
        } catch(e) {}

        // B. Load Notifications
        if(document.getElementById('notifyIssued')) {
            try {
                const res = await fetchAPI('/companies/me/notifications');
                if(res.ok) {
                    const data = await res.json();
                    document.getElementById('notifyIssued').checked = data.notify_issued;
                    document.getElementById('notifySummary').checked = data.notify_summary;
                    document.getElementById('notifySecurity').checked = data.notify_security;
                }
            } catch(e) {}
        }

        // C. Load Branding Images (Preview)
        loadImagePreview('logo', 'logoPreview', 'logoBox');
        loadImagePreview('signature', 'sigPreview', 'sigBox');
    }

    // Helper to load image from backend
    async function loadImagePreview(type, imgId, boxId) {
        try {
            const res = await fetch(`${API_BASE_URL}/companies/me/branding/${type}`, {
                headers: { 'Authorization': `Bearer ${token}` }
            });
            if(res.ok) {
                const blob = await res.blob();
                if (blob.size > 0) {
                    const url = URL.createObjectURL(blob);
                    document.getElementById(imgId).src = url;
                    document.getElementById(boxId).classList.add('has-image');
                }
            }
        } catch(e) { console.error("Image load err", e); }
    }

    // --- 2. Save Notifications ---
    const saveNotifyBtn = document.getElementById('saveNotifyBtn');
    if(saveNotifyBtn) {
        saveNotifyBtn.addEventListener('click', async () => {
            const data = {
                notify_issued: document.getElementById('notifyIssued').checked,
                notify_summary: document.getElementById('notifySummary').checked,
                notify_security: document.getElementById('notifySecurity').checked
            };
            await fetchAPI('/companies/me/notifications', { method: 'PUT', headers: {'Content-Type': 'application/json'}, body: JSON.stringify(data) });
            alert("Preferences Saved!");
        });
    }

    // --- 3. Save Branding ---
    const brandingForm = document.getElementById('brandingForm');
    if(brandingForm) {
        brandingForm.addEventListener('submit', async (e) => {
            e.preventDefault();
            const formData = new FormData();
            const logo = document.getElementById('companyLogo').files[0];
            const sig = document.getElementById('companySignature').files[0];

            if (logo) formData.append('logo', logo);
            if (sig) formData.append('signature', sig);

            if(!logo && !sig) return alert("Select a new file to update.");

            const btn = brandingForm.querySelector('button');
            btn.textContent = "Uploading..."; btn.disabled = true;

            const res = await fetch(`${API_BASE_URL}/companies/me/branding`, { method: 'POST', headers: { 'Authorization': `Bearer ${token}` }, body: formData });

            if(res.ok) alert("Branding Updated! Future certificates will use these.");
            else alert("Upload failed");

            btn.textContent = "Save Branding Assets"; btn.disabled = false;
        });
    }

    // --- 4. Update Profile ---
    const profileForm = document.getElementById('profileForm');
    if(profileForm) {
        profileForm.addEventListener('submit', async (e) => {
            e.preventDefault();
            const data = {
                name: document.getElementById('profileName').value,
                email: document.getElementById('profileEmail').value,
                phone_number: document.getElementById('profilePhone').value
            };
            const res = await fetchAPI('/companies/me/profile', { method: 'PUT', headers: {'Content-Type': 'application/json'}, body: JSON.stringify(data) });
            if(res.ok) alert("Profile Updated!");
        });
    }

    // --- GLOBAL: Instant File Preview ---
    window.previewFile = (input, imgId, boxId) => {
        const file = input.files[0];
        if (file) {
            const reader = new FileReader();
            reader.onload = (e) => {
                document.getElementById(imgId).src = e.target.result;
                document.getElementById(boxId).classList.add('has-image');
            };
            reader.readAsDataURL(file);
        }
    };

    window.switchTab = (tabName) => {
        document.querySelectorAll('.tab-pane').forEach(el => el.classList.remove('active'));
        document.querySelectorAll('.setting-tab').forEach(el => el.classList.remove('active'));
        document.getElementById(`tab-${tabName}`).classList.add('active');
        // Simple active state loop
        const btns = document.querySelectorAll('.setting-tab');
        btns.forEach(b => { if(b.getAttribute('onclick').includes(tabName)) b.classList.add('active'); });
    };

    const logout = document.getElementById('logoutButton');
    if(logout) logout.onclick = () => { localStorage.clear(); window.location.href='login.html'; };

    loadSettings();
});

// frontend/js/contact.js (FINAL DEBUGGED VERSION)

document.addEventListener('DOMContentLoaded', () => {
    // Sticking to Localhost as requested for presentation stability
    const API_BASE_URL = "http://127.0.0.1:8000"; 
    const form = document.getElementById('contactForm');
    const alertBox = document.getElementById('contact-alert');

    if (!form) return;

    form.addEventListener('submit', async (e) => {
        e.preventDefault();
        const btn = document.getElementById('sendContactBtn');
        const originalText = btn.textContent;

        btn.textContent = "Sending...";
        btn.disabled = true;
        alertBox.innerHTML = '';

        const data = {
            name: document.getElementById('contactName').value,
            email: document.getElementById('contactEmail').value,
            message: document.getElementById('contactMessage').value,
        };

        try {
            // Send request to the API
            const response = await fetch(`${API_BASE_URL}/public/contact`, {
                method: 'POST',
                headers: {'Content-Type': 'application/json'},
                body: JSON.stringify(data)
            });

            // If the server connection works, attempt to read result
            const result = await response.json();

            if (response.ok) {
                alertBox.innerHTML = '<div style="color:green;">✅ ' + (result.message || "Message sent successfully.") + '</div>';
                form.reset();
            } else {
                // If backend returns an error (e.g., 400 for bad input)
                throw new Error(result.detail || "Failed to submit form (Server Error).");
            }
        } catch (error) {
            // This catches network failures (DNS/connection) or exceptions thrown above
            alertBox.innerHTML = '<div style="color:red;">❌ Submission Failed: ' + error.message + '</div>';
        } finally {
            btn.textContent = originalText;
            btn.disabled = false;
        }
    });
});

/* frontend/css/dashboard-modern.css */

:root {
    /* Brand Colors */
    --brand-green: #10B981; 
    --brand-blue: #3A86FF;  

    /* UI Colors */
    --bg-body: #F4F7FE;
    --white: #FFFFFF;
    --text-dark: #2B3674;
    --text-gray: #A3AED0;
    --shadow-card: 0px 18px 40px rgba(112, 144, 176, 0.12);
    --border-radius: 20px;

    /* Semantic Colors */
    --danger: #EF4444;
    --warning: #F59E0B;

    --status-active-bg: #D1FAE5;    /* Light Green */
    --status-active-text: #065F46;  /* Dark Green */
    --status-pending-bg: #FFFBEB;   /* Light Yellow */
    --status-pending-text: #B45309; /* Dark Orange */
    --status-revoked-bg: #FEE2E2;   /* Light Red */
    --status-revoked-text: #991B1B;  /* Dark Red */
}

* { box-sizing: border-box; }

body {
    font-family: 'DM Sans', sans-serif;
    background-color: var(--bg-body);
    color: var(--text-dark);
    margin: 0;
    display: flex;
}

/* SIDEBAR & HEADER */
.sidebar {
    width: 280px; background-color: var(--white); height: 100vh; position: fixed;
    padding: 2rem 1.5rem; display: flex; flex-direction: column;
    border-right: 1px solid rgba(0,0,0,0.02); z-index: 100;
}
/* frontend/css/dashboard-modern.css (Logo Alignment Fix) */

.sidebar-header { 
    margin-bottom: 3rem; 
    padding-left: 10px; 
    display: flex; /* CRITICAL: Must be Flex */
    align-items: center; 
    gap: 10px; 
}

/* The DIV that contains the logo image/icon */
/* DELETE THESE OBSOLETE STYLES in dashboard-modern.css */
/* Lines 57-67 in your screenshot are causing the image to float */
.sidebar-header .logo-icon {
    /* REMOVE ALL STYLES FOR THIS CLASS */ 
    width: 40px; 
    height: 40px; 
    background: url('../assets/logo.png') no-repeat center center;
    background-size: contain; 
    color: transparent; 
}
.sidebar-header .logo-icon i {
    display: none; 
}

/* Update the logo text color */
.logo-text { 
    font-size: 1.5rem; 
    font-weight: 800; 
    color: var(--text-dark); 
    letter-spacing: -0.5px;
}
.sidebar-nav { display: flex; flex-direction: column; gap: 8px; flex-grow: 1; }
.sidebar-link {
    display: flex; align-items: center; gap: 15px; padding: 14px 20px; border-radius: 15px;
    color: var(--text-gray); font-weight: 500; text-decoration: none; transition: all 0.3s ease;
}
.sidebar-link:hover { color: var(--brand-blue); background: #EBF3FF; }
.sidebar-link.active { background-color: var(--brand-blue); color: white; box-shadow: 0 10px 20px rgba(58, 134, 255, 0.3); }
.sidebar-footer { margin-top: auto; }
.logout { color: var(--danger); }
.logout:hover { background: #FEF2F2; color: #DC2626; }

/* MAIN CONTENT */
.main-wrapper { margin-left: 280px; width: calc(100% - 280px); padding: 30px; }
.dashboard-header { display: flex; justify-content: space-between; align-items: center; margin-bottom: 2rem; }
.header-left p { font-size: 0.9rem; color: var(--text-gray); margin-bottom: 5px; }
.header-left h1 { font-size: 2rem; font-weight: 700; margin: 0; color: var(--text-dark); }
.header-right { display: flex; align-items: center; gap: 20px; background: var(--white); padding: 10px 20px; border-radius: 30px; box-shadow: var(--shadow-card); }
.user-profile { display: flex; align-items: center; gap: 10px; }
.user-avatar { width: 40px; height: 40px; border-radius: 50%; background: var(--brand-green); color: white; display: flex; align-items: center; justify-content: center; font-weight: bold; }

/* --- FIX: SETTINGS TABS VISIBILITY --- */
.setting-tab {
    display: flex; align-items: center; width: 100%; 
    padding: 18px 20px; 
    background: transparent; border: none; border-radius: 15px;
    cursor: pointer; 
    color: var(--text-gray); /* Default Gray */
    font-weight: 600; 
    transition: 0.3s; margin-bottom: 8px;
    text-align: left;
    font-size: 1rem;
}
.setting-tab i { margin-right: 12px; width: 20px; }

/* Hover State */
.setting-tab:hover { background: #F4F7FE; color: var(--brand-green); }

/* Active State (GREEN Background, WHITE Text) */
.setting-tab.active { 
    background: var(--brand-green) !important; 
    color: #FFFFFF !important; 
    box-shadow: 0 10px 20px rgba(16, 185, 129, 0.3); 
}

/* --- FIX: ACTION BUTTONS (Clearer) --- */
.action-btn-group { display: flex; gap: 10px; }

.icon-btn {
    width: 40px; height: 40px; /* Bigger */
    border-radius: 12px;
    border: 2px solid #F4F7FE; /* Visible Border */
    background: white;
    color: var(--text-gray);
    display: flex; align-items: center; justify-content: center;
    cursor: pointer;
    transition: all 0.2s ease;
}

/* Hover Effects per Type */
.icon-btn:hover { transform: translateY(-2px); }

/* Preview/View (Blue) */
.icon-btn[title*="Preview"], .icon-btn[title*="View"] { color: var(--brand-blue); }
.icon-btn[title*="Preview"]:hover, .icon-btn[title*="View"]:hover { background: #EBF3FF; border-color: var(--brand-blue); }

/* Edit/Email (Green) */
.icon-btn[title*="Edit"], .icon-btn[title*="Email"] { color: var(--brand-green); }
.icon-btn[title*="Edit"]:hover, .icon-btn[title*="Email"]:hover { background: #D1FAE5; border-color: var(--brand-green); }

/* Delete/Revoke (Red) */
.btn-red { color: var(--danger); }
.btn-red:hover { background: #FEF2F2; border-color: var(--danger); color: var(--danger); }


/* --- FIX: SEARCH BOX --- */
.search-box {
    background: var(--bg-body); 
    border: 1px solid transparent; 
    padding: 12px 20px; 
    border-radius: 30px;
    outline: none; 
    color: var(--text-dark); 
    width: 280px;
    font-size: 0.95rem;
    transition: 0.3s;
}
.search-box:focus {
    background: white;
    border-color: var(--brand-green);
    box-shadow: 0 0 0 4px rgba(16, 185, 129, 0.1);
}

/* --- LAYOUTS --- */
.dashboard-grid { display: grid; grid-template-columns: 2fr 1fr; gap: 30px; align-items: start; }
.card { background: var(--white); border-radius: var(--border-radius); padding: 25px; box-shadow: var(--shadow-card); height: 100%; }
.card-header { display: flex; justify-content: space-between; align-items: center; margin-bottom: 20px; }
.card-header h3 { font-size: 1.25rem; font-weight: 700; margin: 0; }

.btn-primary {
    background: var(--brand-green); color: white; border: none;
    padding: 10px 20px; border-radius: 12px; font-weight: 600; cursor: pointer;
    transition: 0.3s; display: inline-flex; align-items: center; gap: 8px;
}
.btn-primary:hover { background: #059669; }

/* Tables */
.table-container { overflow-x: auto; }
.data-table { width: 100%; border-collapse: collapse; }
.data-table th { text-align: left; padding: 15px; color: var(--text-gray); border-bottom: 1px solid #eee; font-weight: 500; font-size: 0.9rem; }
.data-table td { padding: 15px; border-bottom: 1px solid #f4f7fe; color: var(--text-dark); font-weight: 500; }
.status-pill { padding: 5px 12px; border-radius: 20px; font-size: 0.75rem; font-weight: 700; text-transform: uppercase; }
.status-active { background: #D1FAE5; color: #065F46; }
.status-pending { background: #FFFBEB; color: #B45309; }
.status-revoked { background: #FEE2E2; color: #991B1B; }

/* Lists */
.cert-list-item { display: flex; justify-content: space-between; align-items: center; padding: 15px 0; border-bottom: 1px solid #f0f0f0; }
.cert-info { display: flex; align-items: center; gap: 15px; }
.cert-icon { width: 45px; height: 45px; background: #EBF3FF; color: var(--brand-blue); border-radius: 12px; display: flex; align-items: center; justify-content: center; flex-shrink: 0; }
.cert-details h4 { margin: 0; font-size: 1rem; color: var(--text-dark); font-weight: 700; }
.cert-details p { margin: 2px 0 0; font-size: 0.85rem; color: var(--text-gray); }

/* Stats */
.stats-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(240px, 1fr)); gap: 20px; margin-bottom: 30px; }
.stat-card { background: var(--white); border-radius: var(--border-radius); padding: 20px; display: flex; align-items: center; gap: 18px; box-shadow: var(--shadow-card); }
.stat-icon { width: 56px; height: 56px; border-radius: 50%; display: flex; align-items: center; justify-content: center; font-size: 1.5rem; }
.icon-blue { background: #EBF3FF; color: var(--brand-blue); }
.icon-green { background: #D1FAE5; color: var(--brand-green); }
.icon-orange { background: #FFFBEB; color: var(--warning); }
.stat-value { font-size: 1.8rem; font-weight: 700; color: var(--text-dark); }

/* Modals */
.modal-overlay { position: fixed; top:0; left:0; width:100%; height:100%; background: rgba(0,0,0,0.5); display:flex; justify-content:center; align-items:center; z-index:999; backdrop-filter: blur(3px); }
.modal-content { background: white; padding: 30px; border-radius: 20px; width: 90%; max-width: 500px; box-shadow: 0 20px 50px rgba(0,0,0,0.1); }
.modal-header { display:flex; justify-content:space-between; align-items:center; margin-bottom:20px; }
.form-control { width: 100%; padding: 12px; border: 1px solid #E5E7EB; border-radius: 10px; outline: none; }
 .modal-body img {
        /* This ensures the entire image/photo fits without being cropped */
        object-fit: contain !important; 
        max-width: 100%;
        height: auto !important; /* Allow natural height */
        min-height: 100px; /* Prevent it from disappearing */
    }

    /* Iframe Scaling Fix */
    .modal-body iframe {
        width: 100%;
        height: 250px; /* Fixed display height */
        object-fit: contain !important; 
        border: 1px solid #ddd;
    }
