:root {
  --accent-color: #10B981;  
  --primary-color: #3A86FF; 
  --dark-color: #1F2937;    
  --dark-gray-color: #374151;
  --gray-color: #6B7280;
  --light-color: #F9FAFB;   
  --white-color: #FFFFFF;
  --border-color: #E5E7EB;
  --font-family: 'Inter', system-ui, sans-serif;
  --border-radius: 0.75rem;
  --shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.1), 0 2px 4px -2px rgba(0, 0, 0, 0.1);
  --shadow-lg: 0 10px 15px -3px rgba(0, 0, 0, 0.1), 0 4px 6px -4px rgba(0, 0, 0, 0.1);
}

* { box-sizing: border-box; margin: 0; padding: 0; }
html { scroll-behavior: smooth; }
body { font-family: var(--font-family); background-color: var(--white-color); color: var(--dark-gray-color); line-height: 1.6; }
.container { width: 100%; max-width: 1200px; margin: 0 auto; padding: 0 1.5rem; }

/* Buttons */
.btn { display: inline-block; padding: 0.65rem 1.25rem; border-radius: 0.5rem; font-weight: 600; text-align: center; text-decoration: none; border: 1px solid transparent; cursor: pointer; transition: all 0.2s ease-in-out; }
.btn:hover { transform: translateY(-2px); box-shadow: var(--shadow); }
.btn-primary { background-color: var(--accent-color); color: var(--white-color); }
.btn-primary:hover { background-color: #059669; }
.btn-outline { border-color: #D1D5DB; color: var(--dark-gray-color); background-color: var(--white-color); }
.btn-outline:hover { border-color: var(--dark-gray-color); }
.btn-accent { background-color: var(--primary-color); color: var(--white-color); }
.btn-accent:hover { background-color: #2575f5; }
.btn-outline-accent { border-color: var(--accent-color); color: var(--accent-color); background-color: var(--white-color); }
.btn-outline-accent:hover { background-color: var(--accent-color); color: var(--white-color); }
.btn-full { width: 100%; display: flex; align-items: center; justify-content: center; gap: 0.5rem; }
.btn-sm { padding: 0.4rem 0.8rem; font-size: 0.875rem; }

/* Forms & Cards */
.card { background-color: var(--white-color); border-radius: var(--border-radius); box-shadow: var(--shadow); border: 1px solid var(--border-color); padding: 2.5rem; transition: transform 0.3s, box-shadow 0.3s; }
.form-group { display: flex; flex-direction: column; gap: 0.5rem; margin-bottom: 1rem; }
.form-label { font-weight: 500; color: var(--dark-color); }
.form-control { width: 100%; padding: 0.75rem 1rem; border: 1px solid #D1D5DB; border-radius: 0.5rem; font-size: 1rem; transition: all 0.2s; }
.form-control:focus { outline: none; box-shadow: 0 0 0 3px rgba(58, 134, 255, 0.4); border-color: var(--primary-color); }
.divider { display: flex; align-items: center; text-align: center; color: var(--gray-color); margin: 1.5rem 0; }
.divider::before, .divider::after { content: ''; flex-grow: 1; border-bottom: 1px solid var(--border-color); }

/* Header & Footer */
.header { background-color: var(--white-color); border-bottom: 1px solid var(--border-color); position: sticky; top: 0; z-index: 50; padding: 0.75rem 0; }
.nav-container { display: flex; align-items: center; justify-content: space-between; }
.logo { display: flex; align-items: center; gap: 0.5rem; text-decoration: none; }
.logo-icon { width: 40px; 
    height: 40px; 
    background: url('../assets/logo.png') no-repeat center center;
    background-size: contain; 
    color: transparent; }
.logo-text { font-size: 1.25rem; font-weight: 700; color: var(--dark-color); }
.navbar { display: none; gap: 2rem; }
@media (min-width: 768px) { .navbar { display: flex; } }
.nav-link { color: var(--gray-color); font-weight: 500; text-decoration: none; }
.nav-buttons { display: flex; align-items: center; gap: 1rem; }

.footer { background-color: var(--dark-color); color: var(--white-color); padding: 4rem 0 2rem 0; }
.footer-grid { display: grid; grid-template-columns: 1fr; gap: 2.5rem; margin-bottom: 3rem; }
@media (min-width: 768px) { .footer-grid { grid-template-columns: repeat(4, 1fr); } }
.footer-links { list-style: none; display: flex; flex-direction: column; gap: 0.75rem; }
.footer-links a { color: #D1D5DB; text-decoration: none; }
.footer-bottom { border-top: 1px solid var(--dark-gray-color); padding-top: 2rem; text-align: center; font-size: 0.875rem; color: #9CA3AF; }

/* Modals */
.modal-overlay { position: fixed; top: 0; left: 0; width: 100%; height: 100%; background-color: rgba(0, 0, 0, 0.5); display: none; justify-content: center; align-items: center; z-index: 1000; backdrop-filter: blur(2px); }
.modal-content { background: var(--white-color); border-radius: var(--border-radius); width: 90%; max-width: 500px; box-shadow: var(--shadow-lg); animation: slideDown 0.3s ease; }
.modal-header { display: flex; justify-content: space-between; align-items: center; padding: 1.5rem; border-bottom: 1px solid var(--border-color); }
.modal-body { padding: 1.5rem; }
@keyframes slideDown { from { transform: translateY(-20px); opacity: 0; } to { transform: translateY(0); opacity: 1; } }

/* --- STYLE.CSS --- */

/* 1. Global Section Spacing & Layout */
.section { padding: 7rem 0; }
.bg-light { background-color: var(--light-color); }

/* 2. Typography & Hero Styling */
.hero { padding: 6rem 0 8rem 0; overflow: hidden; }
.hero-grid { display: grid; grid-template-columns: 1fr; gap: 4rem; align-items: center; }
@media (min-width: 1024px) { .hero-grid { grid-template-columns: 1fr 1fr; } }

.hero-title { font-size: 3rem; font-weight: 800; line-height: 1.1; color: var(--dark-color); margin-bottom: 1.5rem; }
@media (min-width: 768px) { .hero-title { font-size: 4rem; } }
.hero-title span { color: var(--primary-color); }
.hero-subtitle { font-size: 1.25rem; color: var(--gray-color); max-width: 550px; margin-bottom: 2.5rem; line-height: 1.6; }

.hero-actions { display: flex; flex-direction: column; gap: 1rem; align-items: flex-start; }
.hero-trust { margin-top: 1rem; font-size: 0.95rem; color: var(--gray-color); display: flex; align-items: center; gap: 0.5rem; }

.btn-lg { padding: 1rem 2.5rem; font-size: 1.1rem; }

/* 3. Certificate Card 3D Effect */
.hero-image-wrapper { position: relative; perspective: 1000px; }
.hero-cert-card {
    background-color: var(--white-color);
    border: 1px solid var(--border-color);
    border-radius: 1rem;
    box-shadow: 0 25px 50px -12px rgba(0, 0, 0, 0.25);
    padding: 1.5rem;
    transform: rotateY(-10deg) rotateX(5deg);
    transition: transform 0.5s ease;
}
.hero-image-wrapper:hover .hero-cert-card { transform: rotateY(0) rotateX(0); }

.hero-cert-card-inner { border: 2px dashed var(--border-color); border-radius: 0.5rem; padding: 2rem; text-align: center; }
.cert-header { display: flex; justify-content: space-between; align-items: center; margin-bottom: 1.5rem; }
.cert-status { background: #ECFDF5; color: #059669; padding: 5px 12px; border-radius: 20px; font-size: 0.85rem; font-weight: 600; display: flex; gap: 5px; align-items: center; }
.cert-icon { width: 48px; height: 48px; background: var(--primary-color); color: white; border-radius: 50%; display: flex; align-items: center; justify-content: center; }
.cert-body h3 { font-size: 1.25rem; margin-bottom: 0.5rem; color: var(--dark-color); }
.cert-body p { color: var(--gray-color); margin-bottom: 1.5rem; }
.cert-body span { font-size: 0.875rem; color: var(--gray-color); display: block; }
.cert-placeholder { margin: 0 auto 1rem auto; width: 5rem; height: 5rem; background-color: var(--light-color); border-radius: 0.5rem; display: flex; align-items: center; justify-content: center; color: #9CA3AF; }
.hero-secure-badge { position: absolute; top: -15px; right: -15px; background: var(--accent-color); color: white; padding: 8px 16px; border-radius: 20px; font-weight: bold; box-shadow: var(--shadow); z-index: 10; }

/* 4. VERIFICATION SECTION (Dark Theme) */
.dark-section {
    background: linear-gradient(135deg, #111827 0%, #1F2937 100%);
    color: white;
    position: relative;
}
.verify-content-wrapper {
    display: grid;
    grid-template-columns: 1fr;
    gap: 4rem;
    align-items: center;
}
@media (min-width: 900px) { .verify-content-wrapper { grid-template-columns: 1fr 1fr; } }

.verify-text h2 { margin-bottom: 1.5rem; font-size: 2.5rem; line-height: 1.2; }
.text-white { color: white !important; }
.text-white-dim { color: #D1D5DB !important; font-size: 1.125rem; line-height: 1.7; opacity: 0.9; }

.verify-features { list-style: none; margin-top: 2rem; padding: 0; }
.verify-features li { display: flex; align-items: center; gap: 10px; margin-bottom: 1rem; font-size: 1.1rem; color: #E5E7EB; }
.verify-features li i { color: var(--accent-color); width: 20px; height: 20px; }

.verification-card {
    background: white;
    color: var(--dark-color);
    border-radius: 1rem;
    padding: 3rem;
    box-shadow: 0 20px 25px -5px rgba(0, 0, 0, 0.3);
}

/* 5. Feature Cards */
.features-grid { display: grid; grid-template-columns: 1fr; gap: 2rem; }
@media (min-width: 768px) { .features-grid { grid-template-columns: repeat(3, 1fr); } }
.feature-card {
    background: white; padding: 2.5rem; border-radius: 1rem;
    text-align: center; border: 1px solid transparent;
    transition: all 0.3s ease;
}
.feature-card:hover { transform: translateY(-10px); box-shadow: var(--shadow-lg); border-color: var(--border-color); }
.feature-icon {
    width: 70px; height: 70px; margin: 0 auto 1.5rem auto; border-radius: 1rem;
    display: flex; align-items: center; justify-content: center;
    font-size: 1.5rem;
}
.icon-user { background: #EFF6FF; color: #3B82F6; }
.icon-lock { background: #ECFDF5; color: #10B981; }
.icon-search { background: #FFF7ED; color: #F59E0B; }
.feature-title { font-size: 1.25rem; font-weight: 700; margin-bottom: 0.75rem; color: var(--dark-color); }
.feature-text { color: var(--gray-color); font-size: 1rem; line-height: 1.6; }

/* 6. Content Grid (About) */
.content-grid { display: grid; grid-template-columns: 1fr; gap: 4rem; align-items: center; }
@media (min-width: 1024px) { .content-grid { grid-template-columns: 1fr 1fr; } }
.content-title { font-size: 2.5rem; font-weight: 800; margin-bottom: 1.5rem; color: var(--dark-color); }
.content-subtitle { font-size: 1.125rem; color: var(--gray-color); line-height: 1.7; }
.content-image img { width: 100%; border-radius: 1rem; box-shadow: var(--shadow-lg); }

/* 7. FAQ Styling */
.faq-container { max-width: 800px; margin: 0 auto; }
.faq-list { display: flex; flex-direction: column; gap: 1rem; }
.faq-item { background-color: var(--white-color); padding: 1.5rem; border-radius: 0.75rem; border: 1px solid var(--border-color); }
.faq-question { display: flex; align-items: center; justify-content: space-between; cursor: pointer; font-size: 1.1rem; font-weight: 600; list-style: none; color: var(--dark-color); }
.faq-question::-webkit-details-marker { display: none; }
.faq-answer { margin-top: 1rem; color: var(--gray-color); line-height: 1.6; }

/* 8. Contact Section */
.contact-card { display: grid; grid-template-columns: 1fr; border-radius: 1rem; overflow: hidden; box-shadow: var(--shadow-lg); background: white; margin-top: 2rem; }
@media (min-width: 900px) { .contact-card { grid-template-columns: 2fr 3fr; } }
.contact-info { background: var(--dark-color); color: white; padding: 3rem; }
.contact-info h3 { font-size: 1.5rem; margin-bottom: 1rem; color: white; }
.info-item { display: flex; gap: 1rem; margin-bottom: 1.5rem; align-items: center; opacity: 0.9; }
.contact-form { padding: 3rem; }
.contact-socials { display: flex; gap: 1rem; margin-top: 2rem; padding-top: 1.5rem; border-top: 1px solid rgba(255,255,255,0.1); }
.contact-socials a { color: white; opacity: 0.7; transition: opacity 0.2s; }
.contact-socials a:hover { opacity: 1; }

/* Navbar Buttons */
.nav-buttons { display: flex; gap: 1rem; align-items: center; }

/* frontend/css/auth-sliding.css */

@import url('https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.4.0/css/all.min.css');

:root {
    --primary-grad: linear-gradient(to right, #3A86FF, #2563EB); /* Blue */
    --accent-grad: linear-gradient(to right, #10B981, #059669); /* Green */
    --white: #FFFFFF;
    --gray: #F3F4F6;
}

* { box-sizing: border-box; }

body {
    background: #f6f5f7;
    display: flex;
    justify-content: center;
    align-items: center;
    flex-direction: column;
    font-family: 'Inter', sans-serif;
    height: 100vh;
    margin: 0;
}

h1 { font-weight: 800; margin: 0; }
p { font-size: 14px; font-weight: 100; line-height: 20px; letter-spacing: 0.5px; margin: 20px 0 30px; }
span { font-size: 12px; }
a { color: #333; font-size: 14px; text-decoration: none; margin: 15px 0; }

/* --- SOCIAL ICONS --- */
.social-container { margin: 20px 0; flex-shrink: 0; } /* Prevent shrinking */
.social-container a {
    border: 1px solid #DDDDDD;
    border-radius: 50%;
    display: inline-flex;
    justify-content: center;
    align-items: center;
    margin: 0 5px;
    height: 40px;
    width: 40px;
    color: #333;
    font-size: 18px;
    transition: all 0.3s ease;
    background: white;
}
.social-container a:hover { transform: translateY(-3px); box-shadow: 0 5px 15px rgba(0,0,0,0.1); border-color: transparent; }
.social-container a.fb:hover { background: #3b5998; color: white; }
.social-container a.gl:hover { background: #db4437; color: white; }
.social-container a.li:hover { background: #0077b5; color: white; }

/* --- BUTTONS --- */
button {
    border-radius: 20px;
    border: 1px solid #FFFFFF;
    background-color: #3A86FF;
    color: #FFFFFF;
    font-size: 12px;
    font-weight: bold;
    padding: 12px 45px;
    letter-spacing: 1px;
    text-transform: uppercase;
    transition: transform 80ms ease-in, background-color 0.3s, color 0.3s;
    cursor: pointer;
    margin-top: 10px;
    flex-shrink: 0; /* CRITICAL: Do not squash buttons */
}
button:active { transform: scale(0.95); }
button:focus { outline: none; }

button.ghost { background-color: transparent; border-color: #FFFFFF; }
button.ghost:hover { background-color: #FFFFFF; color: #333; transform: scale(1.05); box-shadow: 0 10px 20px rgba(0,0,0,0.2); }

/* --- FORM & CONTAINER --- */
.container {
    background-color: #fff;
    border-radius: 10px;
    box-shadow: 0 14px 28px rgba(0,0,0,0.25), 0 10px 10px rgba(0,0,0,0.22);
    position: relative;
    overflow: hidden;
    width: 900px;
    max-width: 100%;
    height: 650px;
}

.form-container { position: absolute; top: 0; height: 100%; transition: all 0.6s ease-in-out; }

form {
    background-color: #FFFFFF;
    display: flex;
    align-items: center;
    justify-content: center;
    flex-direction: column;
    padding: 0 50px;
    height: 100%;
    text-align: center;
}

/* SCROLL FIX FOR REGISTER PAGE */
.sign-up-container form { 
    justify-content: flex-start; /* Start from top */
    overflow-y: auto; /* Enable Scroll */
    padding-top: 40px; 
    padding-bottom: 20px; 
}
.sign-up-container form::-webkit-scrollbar { width: 6px; }
.sign-up-container form::-webkit-scrollbar-thumb { background-color: #ccc; border-radius: 4px; }

/* --- INPUTS --- */
/* CRITICAL FIX: flex-shrink: 0 prevents squashing */
input:not([type="checkbox"]), select {
    background-color: #eee;
    border: none;
    padding: 0 15px; 
    margin: 8px 0;
    width: 100%;
    border-radius: 8px;
    outline: none;
    height: 45px;      /* Force Height */
    min-height: 45px;  /* Force Min Height */
    font-size: 14px;
    flex-shrink: 0;    /* PREVENT SQUASHING */
}

/* PASSWORD CONTAINER */
.password-container {
    position: relative;
    width: 100%;
    margin: 8px 0;
    height: 45px;
    min-height: 45px;
    flex-shrink: 0; /* PREVENT SQUASHING */
}

.password-container input {
    margin: 0; 
    height: 100%; 
    padding-right: 40px;
}

.toggle-password {
    position: absolute;
    right: 15px;
    top: 50%;
    transform: translateY(-50%);
    cursor: pointer;
    color: #9CA3AF;
    font-size: 1rem;
    z-index: 10;
}
.toggle-password:hover { color: #3A86FF; }

/* --- FILE INPUT --- */
.file-input-group { 
    width: 100%; 
    margin: 8px 0; 
    text-align: left; 
    flex-shrink: 0; /* PREVENT SQUASHING */
}

.file-input-label {
    display: flex; align-items: center; justify-content: center;
    background-color: #f0fdf4; border: 1px dashed #10B981;
    color: #10B981; padding: 0 15px; border-radius: 8px;
    cursor: pointer; font-size: 0.9rem; transition: all 0.3s; font-weight: 600;
    height: 45px;      /* Match inputs */
    min-height: 45px;  /* Match inputs */
}
.file-input-label:hover { background-color: #10B981; color: white; }
.file-input-label i { margin-right: 8px; }
.file-name-display { font-size: 0.75rem; color: #666; margin-left: 5px; display: block; margin-top: 2px; }
input[type="file"] { display: none; }

/* --- SECTIONS --- */
.section-title { 
    width:100%; text-align:left; font-size:0.75rem; font-weight:800; 
    color:#9ca3af; letter-spacing:1px; margin:20px 0 5px 0; 
    text-transform:uppercase; 
    flex-shrink: 0; /* PREVENT SQUASHING */
}

/* --- ANIMATION LAYOUT --- */
.sign-in-container { left: 0; width: 50%; z-index: 2; }
.container.right-panel-active .sign-in-container { transform: translateX(100%); }

.sign-up-container { left: 0; width: 50%; opacity: 0; z-index: 1; }
.container.right-panel-active .sign-up-container { transform: translateX(100%); opacity: 1; z-index: 5; animation: show 0.6s; }

@keyframes show { 0%, 49.99% { opacity: 0; z-index: 1; } 50%, 100% { opacity: 1; z-index: 5; } }

.overlay-container { position: absolute; top: 0; left: 50%; width: 50%; height: 100%; overflow: hidden; transition: transform 0.6s ease-in-out; z-index: 100; }
.container.right-panel-active .overlay-container { transform: translateX(-100%); }

.overlay { background: var(--accent-grad); background-repeat: no-repeat; background-size: cover; background-position: 0 0; color: #FFFFFF; position: relative; left: -100%; height: 100%; width: 200%; transform: translateX(0); transition: transform 0.6s ease-in-out; }
.container.right-panel-active .overlay { background: var(--primary-grad); transform: translateX(50%); }

.overlay-panel { position: absolute; display: flex; align-items: center; justify-content: center; flex-direction: column; padding: 0 40px; text-align: center; top: 0; height: 100%; width: 50%; transform: translateX(0); transition: transform 0.6s ease-in-out; }
.overlay-left { transform: translateX(-20%); }
.container.right-panel-active .overlay-left { transform: translateX(0); }
.overlay-right { right: 0; transform: translateX(0); }
.container.right-panel-active .overlay-right { transform: translateX(20%); }

:root { --sidebar-width: 260px; --dashboard-bg: #F9FAFB; }
.dashboard-body { display: flex; background-color: var(--dashboard-bg); min-height: 100vh; }

/* Sidebar */
.sidebar { width: var(--sidebar-width); background-color: var(--white-color); border-right: 1px solid var(--border-color); position: fixed; height: 100vh; display: flex; flex-direction: column; padding: 1.5rem; z-index: 100; }
.sidebar-header { margin-bottom: 2.5rem; }
.sidebar-nav { display: flex; flex-direction: column; gap: 0.5rem; }
.sidebar-link { display: flex; align-items: center; gap: 1rem; padding: 0.75rem 1rem; border-radius: 0.5rem; color: var(--gray-color); font-weight: 500; text-decoration: none; transition: 0.2s; }
.sidebar-link:hover { background-color: var(--light-color); color: var(--dark-color); }
.sidebar-link.active { background-color: var(--primary-color); color: var(--white-color); }
.sidebar-footer { margin-top: auto; }

/* Main Content */
.main-wrapper { margin-left: var(--sidebar-width); flex-grow: 1; padding: 2rem; width: calc(100% - var(--sidebar-width)); }
.dashboard-header { display: flex; justify-content: space-between; align-items: center; margin-bottom: 2rem; }
.user-profile { display: flex; align-items: center; gap: 1rem; }
.user-avatar { width: 40px; height: 40px; background-color: var(--accent-color); color: var(--white-color); border-radius: 50%; display: flex; align-items: center; justify-content: center; font-weight: 700; }

/* Stats & Grid */
.stats-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(240px, 1fr)); gap: 1.5rem; margin-bottom: 2rem; }
.stat-card { background: white; padding: 1.5rem; border-radius: var(--border-radius); border: 1px solid var(--border-color); display: flex; align-items: center; gap: 1rem; }
.stat-icon { width: 50px; height: 50px; border-radius: 50%; display: flex; align-items: center; justify-content: center; font-size: 1.2rem; }
.stat-value { font-size: 1.5rem; font-weight: 700; color: var(--dark-color); display: block; }
.dashboard-grid { display: grid; grid-template-columns: 2fr 1fr; gap: 1.5rem; }
@media (max-width: 1024px) { .dashboard-grid { grid-template-columns: 1fr; } }

/* Tables */
.table-container { overflow-x: auto; background: white; border-radius: var(--border-radius); border: 1px solid var(--border-color); }
.data-table { width: 100%; border-collapse: collapse; }
.data-table th, .data-table td { padding: 1rem; text-align: left; border-bottom: 1px solid var(--border-color); }
.data-table th { background: #F9FAFB; font-weight: 600; color: var(--gray-color); }
.status-pill { padding: 0.25rem 0.75rem; border-radius: 99px; font-size: 0.85rem; font-weight: 600; }
.status-active { background: #D1FAE5; color: #065F46; }
.status-pending { background: #FEF3C7; color: #92400E; }
.status-suspended, .status-rejected { background: #FEE2E2; color: #991B1B; }

/* Cert List */
.cert-list { display: flex; flex-direction: column; gap: 1rem; margin-top: 1rem; }
.cert-list-item { display: flex; justify-content: space-between; align-items: center; padding: 1rem; border: 1px solid var(--border-color); border-radius: 0.5rem; background: white; }
.cert-info { display: flex; align-items: center; gap: 1rem; }
.action-btn-group { display: flex; gap: 0.5rem; }
.icon-btn { width: 32px; height: 32px; display: flex; align-items: center; justify-content: center; border: 1px solid #E5E7EB; background: white; border-radius: 6px; cursor: pointer; color: #4B5563; }
.icon-btn:hover { background: #F3F4F6; }
.btn-red:hover { background: #FEF2F2; color: #DC2626; border-color: #FCA5A5; }
